on conflict (row_id) do update set organization_id = excluded.organization_id, location_id = excluded.location_id, id = excluded.id, po_number = excluded.po_number, material_id = excluded.material_id, material_name = excluded.material_name, code = excluded.code, unit = excluded.unit, unit_cost = excluded.unit_cost, ordered_qty = excluded.ordered_qty, received_qty = excluded.received_qty, rejected_qty = excluded.rejected_qty, server_created_at = excluded.server_created_at, server_updated_at = excluded.server_updated_at, updated_by = excluded.updated_by, deleted_at = excluded.deleted_at, gst_pct = excluded.gst_pct, unit_cost_minor = excluded.unit_cost_minor;
-- purchase_events: 5 row(s)
insert into public.purchase_events (organization_id, location_id, po_row_id, price_row_id, action, actor, meta, created_at)
select organization_id, location_id, po_row_id, price_row_id, action, actor, meta, created_at from jsonb_populate_recordset(null::public.purchase_events, $rows$[{"id": 1, "meta": {"lines": 4, "number": "SPO-0001", "status": "Pending", "supplier_id": "sup_b9f54a9e65de4092a0b91aec7a7c38e6"}, "actor": "731e2dff-24d5-4b2a-ad54-d4493447e376", "action": "po_create", "po_row_id": "9543a840-49f9-4c59-a330-31721dc8c4c6", "created_at": "2026-10-28T05:28:12.764559+00:00", "location_id": "7b0b7ead-af89-43bb-bba5-dff5841a3558", "price_row_id": null, "organization_id": "bd4d8ee9-5885-41e4-b6a1-ba2b9cb873dd"}, {"id": 2, "meta": {"lines": 3, "number": "SPO-0002", "status": "Pending", "supplier_id": "sup_4aba26a216ec483fbb6d16f6d145a0dc"}, "actor": "731e2dff-24d5-4b2a-ad54-d4493447e376", "action": "po_create", "po_row_id": "41060b2e-bede-49b1-8c06-e51a57b0005f", "created_at": "2026-10-28T05:28:12.764559+00:00", "location_id": "7b0b7ead-af89-43bb-bba5-dff5841a3558", "price_row_id": null, "organization_id": "bd4d8ee9-5885-41e4-b6a1-ba2b9cb873dd"}, {"id": 3, "meta": {"lines": 3, "number": "SPO-0003", "status": "Pending", "supplier_id": "sup_35aa6ca29cd3495dbf1351593142c95f"}, "actor": "731e2dff-24d5-4b2a-ad54-d4493447e376", "action": "po_create", "po_row_id": "ee9b9c13-aef5-416e-8965-63efb3f5447b", "created_at": "2026-10-28T05:28:12.764559+00:00", "location_id": "7b0b7ead-af89-43bb-bba5-dff5841a3558", "price_row_id": null, "organization_id": "bd4d8ee9-5885-41e4-b6a1-ba2b9cb873dd"}, {"id": 4, "meta": {"lines": 2, "number": "SPO-0004", "status": "Pending", "supplier_id": "sup_b9f54a9e65de4092a0b91aec7a7c38e6"}, "actor": "731e2dff-24d5-4b2a-ad54-d4493447e376", "action": "po_create", "po_row_id": "9f7c4dca-397b-45ff-984b-739e9ebed3f0", "created_at": "2026-10-28T05:28:12.764559+00:00", "location_id": "7b0b7ead-af89-43bb-bba5-dff5841a3558", "price_row_id": null, "organization_id": "bd4d8ee9-5885-41e4-b6a1-ba2b9cb873dd"}, {"id": 5, "meta": {"to": "******0011", "number": "SPO-0004", "channel": "whatsapp", "supplier_id": "sup_b9f54a9e65de4092a0b91aec7a7c38e6"}, "actor": "731e2dff-24d5-4b2a-ad54-d4493447e376", "action": "po_sent", "po_row_id": "9f7c4dca-397b-45ff-984b-739e9ebed3f0", "created_at": "2026-10-28T05:28:12.764559+00:00", "location_id": "7b0b7ead-af89-43bb-bba5-dff5841a3558", "price_row_id": null, "organization_id": "bd4d8ee9-5885-41e4-b6a1-ba2b9cb873dd"}]$rows$::jsonb) r
where not exists (select 1 from public.purchase_events e where e.po_row_id = r.po_row_id and e.created_at = r.created_at);

-- opening stock: what 100 of every dish needs (with wastage), less what is on hand, at the main outlet
insert into public.stock_movements (organization_id, location_id, inventory_item_id, kind, quantity, unit_cost_minor, ref_type, ref_id, note)
select n.org, (select l.id from public.locations l where l.organization_id = n.org order by (l.code = 'MAIN') desc, l.created_at limit 1),
       n.item, 'receipt', n.need - n.on_hand, coalesce(p.cost_minor, 0), 'opening_stock', 'ai-recipes-100', 'Opening stock for 100 of each dish'
  from (select mr.organization_id as org, mr.inventory_item_id as item,
               ceil(sum(100 * mr.qty_per_unit * (1 + mr.wastage_pct / 100)) * 1000) / 1000 as need,
               public.mb_on_hand(mr.organization_id, mr.inventory_item_id) as on_hand
          from public.menu_item_recipes mr where mr.organization_id = 'bd4d8ee9-5885-41e4-b6a1-ba2b9cb873dd'
         group by mr.organization_id, mr.inventory_item_id) n
  left join public.ingredient_profiles p on p.inventory_item_id = n.item
 where n.need - n.on_hand > 0;

set constraints all immediate; -- place the new stock in its bins now

notify pgrst, 'reload schema';
commit;
